// ─── File: src/test/java/com/bank/anon/AnonymousSubclassTest.java ───
package com.bank.anon;

import org.junit.jupiter.api.Test;
import java.math.BigDecimal;
import java.util.*;
import static org.assertj.core.api.Assertions.*;

class AnonymousSubclassTest {

    // ═══ CANNOT instantiate abstract class directly ═══
    @Test
    void abstractClass_cannotInstantiateDirectly() {
        // Account account = new Account("SAV001", BigDecimal.ZERO);
        // (Avoid) COMPILE ERROR: "Cannot instantiate the type Account"
        assertThat(java.lang.reflect.Modifier.isAbstract(Account.class.getModifiers())).isTrue();
    }

    // ═══ CAN create anonymous subclass ═══
    @Test
    void anonymousSubclass_implementsInline() {
        Account anon = new Account("ANON001", new BigDecimal("50000")) {
            @Override public BigDecimal calculateInterest() {
                return getBalance().multiply(new BigDecimal("0.03"));
            }
            @Override public String getType() { return "ANONYMOUS"; }
        };

        assertThat(anon.getAccountId()).isEqualTo("ANON001");
        assertThat(anon.calculateInterest()).isEqualByComparingTo("1500");
        assertThat(anon.getType()).isEqualTo("ANONYMOUS");
    }

    @Test
    void anonymousSubclass_hasNoName() {
        Account anon = new Account("X", BigDecimal.ZERO) {
            @Override public BigDecimal calculateInterest() { return BigDecimal.ZERO; }
            @Override public String getType() { return "TEST"; }
        };
        assertThat(anon.getClass().getSimpleName()).isEmpty();  // truly anonymous!
        assertThat(anon.getClass().getName()).contains("$");     // compiler-generated name
        assertThat(anon).isInstanceOf(Account.class);            // IS-A Account
    }

    // ═══ Useful in tests — quick one-off implementation ═══
    @Test
    void anonymousSubclass_usefulForTests() {
        // No need to create a TestAccount.java file — inline!
        Account testAccount = new Account("TEST001", new BigDecimal("100000")) {
            @Override public BigDecimal calculateInterest() { return BigDecimal.ZERO; }
            @Override public String getType() { return "TEST_FIXTURE"; }
        };

        // Use in test:
        BigDecimal interest = testAccount.calculateInterest();
        assertThat(interest).isEqualByComparingTo("0");
    }

    // ═══ Anonymous class for Comparator (pre-lambda pattern) ═══
    @Test
    void anonymousClass_comparator_preLambda() {
        List<String> symbols = new ArrayList<>(List.of("TCS", "RELIANCE", "HDFC"));

        // Pre-lambda: anonymous Comparator
        symbols.sort(new Comparator<String>() {
            @Override public int compare(String a, String b) {
                return Integer.compare(a.length(), b.length());
            }
        });
        assertThat(symbols).containsExactly("TCS", "HDFC", "RELIANCE");

        // Post-lambda: much shorter!
        symbols.sort((a, b) -> Integer.compare(a.length(), b.length()));
        // Or: symbols.sort(Comparator.comparingInt(String::length));
    }

    // ═══ Lambda CANNOT replace anonymous for abstract classes ═══
    @Test
    void lambda_cannotReplaceAbstractClass() {
        // Account lambda = (...) -> { ... };
        // (Avoid) COMPILE ERROR: Account is not a functional interface!
        // Lambdas ONLY work for interfaces with ONE abstract method.
        // Abstract classes with state + constructor → must use anonymous subclass.
        assertThat(true).isTrue();
    }

    // ═══ POLYMORPHISM works with anonymous subclass ═══
    @Test
    void anonymousSubclass_worksPolymorphically() {
        List<Account> accounts = List.of(
            new Account("A1", new BigDecimal("100000")) {
                @Override public BigDecimal calculateInterest() {
                    return getBalance().multiply(new BigDecimal("0.04"));
                }
                @Override public String getType() { return "SAVINGS"; }
            },
            new Account("A2", new BigDecimal("200000")) {
                @Override public BigDecimal calculateInterest() { return BigDecimal.ZERO; }
                @Override public String getType() { return "CURRENT"; }
            }
        );

        BigDecimal total = accounts.stream()
            .map(Account::calculateInterest)  // polymorphic!
            .reduce(BigDecimal.ZERO, BigDecimal::add);

        assertThat(total).isEqualByComparingTo("4000");  // 100000×4% + 0
    }
}
